// Store RPC response topic if present
if (msg.rpcResponseTopic) {
    flow.set("lds_rpc_response_topic", msg.rpcResponseTopic);
}

// Daily and Total load energy
// 626: Day_Load_Power (0.1kWh)
// 627: Total_Load_Energy Low (0.1kWh)
// 628: Total_Load_Energy High (0.1kWh)

msg.baseAddr = 626;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 626,
    quantity: 3
};
return msg;

// UPS Load power - LOW words
// 740: UPS load phase A LOW (1W, U32)
// 741: UPS load phase B LOW (1W, U32)
// 742: UPS load phase C LOW (1W, U32)
// 743: UPS load total LOW (1W, U32)

msg.baseAddr = 740;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 740,
    quantity: 4
};
return msg;

// UPS Load power - HIGH words
// 796: UPS load phase A HIGH (1W, U32)
// 797: UPS load phase B HIGH (1W, U32)
// 798: UPS load phase C HIGH (1W, U32)
// 799: UPS load total HIGH (1W, U32)

msg.baseAddr = 796;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 796,
    quantity: 4
};
return msg;

// Load phase voltages
// 744: Load phase voltage A (0.1V)
// 745: Load phase voltage B (0.1V)
// 746: Load phase voltage C (0.1V)

msg.baseAddr = 744;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 744,
    quantity: 3
};
return msg;

// Load power - LOW words
// 750: Load phase A power LOW (1W, S32)
// 751: Load phase B power LOW (1W, S32)
// 752: Load phase C power LOW (1W, S32)
// 753: Load total power LOW (1W, S32)

msg.baseAddr = 750;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 750,
    quantity: 4
};
return msg;

// Load power - HIGH words
// 756: Load phase A power HIGH (1W, S32)
// 757: Load phase B power HIGH (1W, S32)
// 758: Load phase C power HIGH (1W, S32)
// 759: Load total power HIGH (1W, S32)

msg.baseAddr = 756;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 756,
    quantity: 4
};
return msg;

// Load frequency
// 755: Load frequency (0.01Hz)

msg.baseAddr = 755;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 755,
    quantity: 1
};
return msg;

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    return null;
}

function s32(low, high) {
    const u = ((high & 0xFFFF) << 16) | (low & 0xFFFF);
    return (u & 0x80000000) ? u - 0x100000000 : u;
}

function u32(low, high) {
    return ((high & 0xFFFF) << 16) | (low & 0xFFFF);
}

// Daily/Total 626-628
if (baseAddr === 626) {
    const daily = data[0] || 0;
    const totalLow = data[1] || 0;
    const totalHigh = data[2] || 0;

    flow.set("lds_part_energy", {
        todayEnergyKWh: Math.round(daily * 0.1 * 100) / 100,
        totalEnergyKWh: Math.round(u32(totalLow, totalHigh) * 0.1 * 100) / 100
    });
}

// UPS Power Low 740-743
else if (baseAddr === 740) {
    flow.set("lds_part_ups_low", {
        phaseA: data[0] || 0,
        phaseB: data[1] || 0,
        phaseC: data[2] || 0,
        total: data[3] || 0
    });
}

// UPS Power High 796-799
else if (baseAddr === 796) {
    const low = flow.get("lds_part_ups_low");
    if (low) {
        flow.set("lds_part_ups_power", {
            phaseAPowerW: u32(low.phaseA, data[0]),
            phaseBPowerW: u32(low.phaseB, data[1]),
            phaseCPowerW: u32(low.phaseC, data[2]),
            totalPowerW: u32(low.total, data[3])
        });
    }
}

// Voltage 744-746
else if (baseAddr === 744) {
    flow.set("lds_part_voltage", {
        phaseAVoltageV: Math.round(data[0] * 0.1 * 10) / 10,
        phaseBVoltageV: Math.round(data[1] * 0.1 * 10) / 10,
        phaseCVoltageV: Math.round(data[2] * 0.1 * 10) / 10
    });
}

// Load Power Low 750-753
else if (baseAddr === 750) {
    flow.set("lds_part_load_low", {
        phaseA: data[0] || 0,
        phaseB: data[1] || 0,
        phaseC: data[2] || 0,
        total: data[3] || 0
    });
}

// Load Power High 756-759
else if (baseAddr === 756) {
    const low = flow.get("lds_part_load_low");
    if (low) {
        flow.set("lds_part_load_power", {
            phaseAPowerW: s32(low.phaseA, data[0]),
            phaseBPowerW: s32(low.phaseB, data[1]),
            phaseCPowerW: s32(low.phaseC, data[2]),
            totalActivePowerW: s32(low.total, data[3])
        });
    }
}

// Freq 755
else if (baseAddr === 755) {
    flow.set("lds_part_freq", {
        frequencyHz: Math.round((data[0] || 0) * 0.01 * 100) / 100
    });
}
else {
    return null;
}

// Assemble
const energyPart = flow.get("lds_part_energy");
const upsPowerPart = flow.get("lds_part_ups_power");
const voltagePart = flow.get("lds_part_voltage");
const loadPowerPart = flow.get("lds_part_load_power");
const freqPart = flow.get("lds_part_freq");

if (!energyPart || !upsPowerPart || !voltagePart || !loadPowerPart || !freqPart) {
    return null;
}

const deviceId = msg.deviceId || global.get("DEVICE_ID") || env.get("DEVICE_ID") || "EC100";

const state = {
    kind: "LoadDeviceState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    scope: "backup_load",

    loadPower: {
        totalActivePowerW: loadPowerPart.totalActivePowerW,
        phaseAPowerW: loadPowerPart.phaseAPowerW,
        phaseBPowerW: loadPowerPart.phaseBPowerW,
        phaseCPowerW: loadPowerPart.phaseCPowerW
    },

    loadVoltage: {
        phaseAVoltageV: voltagePart.phaseAVoltageV,
        phaseBVoltageV: voltagePart.phaseBVoltageV,
        phaseCVoltageV: voltagePart.phaseCVoltageV
    },

    frequencyHz: freqPart.frequencyHz,

    upsLoadPower: {
        totalPowerW: upsPowerPart.totalPowerW,
        phaseAPowerW: upsPowerPart.phaseAPowerW,
        phaseBPowerW: upsPowerPart.phaseBPowerW,
        phaseCPowerW: upsPowerPart.phaseCPowerW
    },

    todayEnergyKWh: energyPart.todayEnergyKWh,
    totalEnergyKWh: energyPart.totalEnergyKWh
};

// Clear partials
flow.set("lds_part_energy", null);
flow.set("lds_part_ups_low", null);
flow.set("lds_part_ups_power", null);
flow.set("lds_part_voltage", null);
flow.set("lds_part_load_low", null);
flow.set("lds_part_load_power", null);
flow.set("lds_part_freq", null);

flow.set("loadDeviceStateSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;

const rpcTopic = flow.get("lds_rpc_response_topic");
if (!rpcTopic) {
    return null;
}

const state = msg.state || msg.payload;
msg.payload = { success: true, data: state };
msg.topic = rpcTopic;

flow.set("lds_rpc_response_topic", null);
return msg;
